var async = require('async');
var elastical = require('elastical');
var config = require('../../config');

var db = new elastical.Client(config.elasticSearch.host, {port: config.elasticSearch.port, timeout: config.elasticSearch.timeout});

db.wipeIndex = function(indexName, cb) {
  db.indexExists(indexName, function(err, exists){
    if (err) return cb(err);
    if (exists) {
      return db.deleteIndex(indexName, cb);
    }
    return cb();
  });
  return db;
};

db.recreate = function(indexName, mapping, cb) {
  var map = require('./'+mapping+'-mapping.json');
  var settings = require('./settings.json');

  var tasks = [];
  tasks.push(function(done){
    db.wipeIndex(indexName, done);
  });
  tasks.push(function(done){
    db.createIndex(indexName, {settings: settings}, done);
  });
  tasks.push(function(done){
    db.putMapping(indexName, mapping, map, done);
  });
  async.series(tasks, cb);
  return db;
};


db.dump = function(cb) {
  db.search(function(err, res){
    if (err) return cb(err);
    var docs = res.hits.map(function(doc){
      var out = doc._source;
      out._id = doc._id;
      return out;
    });
    cb(null, docs);
  });
  return db;
};


db.import = function(index, type, docs, cb) {
  var doIt = function(doc, done) {
    var opt = {refresh: true};
    if (doc._id) opt.id = doc._id;
    db.index(index, type, doc, opt, done);
  };
  async.map(docs, doIt, cb);
  return db;
};

module.exports = db;

