var child_process = require('child_process');

var mysql = require('mysql');
var config = require('../../config');

var opt = {
  connectionLimit: config.mysql.maxConnections
};

var db = mysql.createPool(config.mysql.uri, opt);

db.dump = function(cb) {
  var opt = db.config.connectionConfig;

  var args = [];
  args.push("-h");
  args.push(opt.host);
  args.push("-P");
  args.push(opt.port);

  if (opt.user) args.push("--user="+opt.user);
  if (opt.password) args.push("--password="+opt.password);
  if (opt.database) {
    args.push(opt.database);
  } else {
    args.push("--all-databases");
  }

  args.push("--set-gtid-purged=OFF");

  var stderr = "";
  var stdout = "";

  var proc = child_process.spawn("mysqldump", args);
  proc.stdout.on('data', function(data){
    stdout += String(data);
  });
  proc.stderr.on('data', function(data){
    data = String(data);
    if (data.indexOf('Warning') === 0) return;
    stderr += data;
  });
  proc.on('exit', function(code){
    var err;
    if (code !== 1 && stderr) {
      err = new Error(stderr);
    }
    cb(err, stdout, code);
  });
  return db;
};

db.import = function(sqlData, cb) {
  var opt = db.config.connectionConfig;
  var args = [];

  args.push("--host="+opt.host);
  args.push("--port="+opt.port);

  if (opt.user) args.push("--user="+opt.user);
  if (opt.password) args.push("--password="+opt.password);

  var stderr = "";
  var stdout = "";

  var proc = child_process.spawn("mysql", args);
  proc.stdout.on('data', function(data){
    stdout += String(data);
  });
  proc.stderr.on('data', function(data){
    data = String(data);
    if (data.indexOf('Warning') === 0) return;
    stderr += data;
  });
  proc.on('exit', function(code){
    var err;
    if (code !== 1 && stderr) {
      err = new Error(stderr);
    }
    cb(err, stdout, code);
  });

  proc.stdin.write("DROP DATABASE IF EXISTS "+opt.database+";\n");
  proc.stdin.write("CREATE DATABASE "+opt.database+";\n");
  proc.stdin.write("USE "+opt.database+";\n");
  proc.stdin.write(String(sqlData));
  proc.stdin.end();
  return db;
};

module.exports = db;

