var request = require('request'),
  winston = require('winston'),
  util = require('util');

module.exports = winston.transports.Loggly = Loggly;

function Loggly (opt) {
  if (!opt.token) throw new Error("Missing token");

  this.name = 'Loggly';
  this.level = opt.level || 'info';
  this.appName = opt.name || 'default';
  this.uri = "http://logs-01.loggly.com/inputs/"+opt.token;
}

util.inherits(Loggly, winston.Transport);

Loggly.prototype.log = function (level, msg, meta, cb) {
  var json = {
    time: Date.now(),
    level: level,
    text: msg,
    meta: meta
  };

  var req = {
    url: this.uri,
    method: 'POST',
    headers: {
      'X-LOGGLY-TAG': this.appName
    },
    json: json
  };

  request(req, cb);
};

